function annual(hourly, hoursPerWeek, weeksPerYear){ return hourly*hoursPerWeek*weeksPerYear; }
function hourly(annual, hoursPerWeek, weeksPerYear){ var d=hoursPerWeek*weeksPerYear; if(d===0) return null; return annual/d; }
function monthly(annual){ if(annual==null) return null; return annual/12; }
function weekly(annual, weeksPerYear){ if(!weeksPerYear) return null; return annual/weeksPerYear; }
var EXPORTS={annual:annual, hourly:hourly, monthly:monthly, weekly:weekly};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WageForgePure = EXPORTS; }
